#!/usr/bin/env python3
# ⚠ DO NOT REMOVE - builds erp/ad_ddl_notnull.js: the legacy schema's NOT NULL columns (bim-ootb prompts/CAPEX_DASHBOARD.md §5.73, G2).
# WHY: legacy refuses a row with no value in a NOT NULL column in the DATABASE ("ERROR: null value in column ... violates not-null constraint"); PO.saveNew has no Java check
#   (PO.java:3520; isMandatoryOK :2104 is deprecated and uncalled), and AD_Column.IsMandatory is a different set. The twin's SQLite tables carry no NOT NULL, so the list is data.
# Per table: the columns in ordinal_position order (Postgres names the first failing attribute); a trailing * marks a column with a physical DEFAULT (never refused at INSERT:
#   PO.doInsert omits null columns, PO.java:3735). A default of NULL (M_Shipper.Name: NULL::character varying) fills nothing, so it is not flagged (found by W-DDL-NOTNULL N1). Read the §DDL_NOTNULL line on stderr after every run.
# Run: python3 erp/patches/build_ddl_notnull.py [database] > erp/ad_ddl_notnull.js   (postgres container up; default database `idempiere`)
import subprocess, sys, json
dbn = sys.argv[1] if len(sys.argv) > 1 else 'idempiere'
rows = subprocess.check_output(['docker', 'exec', '-i', 'postgres', 'psql', '-U', 'postgres', '-d', dbn, '-tA', '-F', '|', '-c',
    "select c.table_name, c.column_name, case when c.column_default is null or c.column_default ~* '^NULL(::.*)?$' then '' else '*' end from information_schema.columns c "
    "join information_schema.tables t on t.table_schema=c.table_schema and t.table_name=c.table_name "
    "where c.table_schema='adempiere' and t.table_type='BASE TABLE' and c.is_nullable='NO' order by c.table_name, c.ordinal_position"], text=True).splitlines()
tabs, n, nd = {}, 0, 0
for r in rows:
    t, c, d = r.split('|')
    tabs.setdefault(t, []).append(c + d); n += 1; nd += 1 if d else 0
print('// Copyright (c) 2025-2026 Redhuan D. Oon <red1org@gmail.com>')
print('// SPDX-License-Identifier: MIT')
print('// GENERATED by erp/patches/build_ddl_notnull.py - do not edit. Legacy iDempiere\'s NOT NULL columns (information_schema.columns, is_nullable=NO), per table in ordinal order; * = has a physical DEFAULT.')
print('// %d columns on %d tables (%d with a default). Read by model_layer.js notNullError (NOT part of the hashed base patches; no table is written to the DB).' % (n, len(tabs), nd))
print('(function (g) { var L = ' + json.dumps({t: ','.join(cs) for t, cs in sorted(tabs.items())}, separators=(',', ':')).replace('","', '",\n"') + ';')
print("  if (typeof module !== 'undefined' && module.exports) module.exports = L; g.AD_DDL_NOTNULL = L; })(typeof window !== 'undefined' ? window : globalThis);")
sys.stderr.write('§DDL_NOTNULL database=%s columns=%d tables=%d with_default=%d\n' % (dbn, n, len(tabs), nd))
